 {page==='products'&&<><ProductCatalogForm saving={saving} onSave={product=>persist({...shop,products:[...shop.products,product]})}/><section className="panel"><div className="panel-title"><h2>Danh mục sản phẩm</h2><span className="count-pill">{productSales.length} sản phẩm</span></div><div className="product-grid">{productSales.map((p,i)=><article className="product-card" key={p.name}><div className={'product-art art-'+i}>{productImage(p.name)?<img src={productImage(p.name)} alt={p.name} loading="lazy" width={1086} height={1448}/>:<><Shirt size={70} strokeWidth={1}/><span>EMI HOUSE</span></>}</div><div className="product-card-body"><h3>{p.name}</h3><p>Giá bán chuẩn <strong>{money(p.price)}</strong></p><p>Giá vốn / sản phẩm <strong>{money(p.cost)}</strong></p><div className="product-card-bottom"><span>{p.qty} đã bán</span><strong>{money(p.total)}</strong></div></div></article>)}</div>{!productSales.length&&<Empty text="Thêm sản phẩm đầu tiên để bắt đầu tạo đơn."/>}</section></>}
 {page==='settings'&&<div className="settings-grid"><section className="panel settings-panel"><h2>Thiết lập chi phí</h2><form key={revision} onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const settings={shipping:Number(f.get('shipping')),returnShipping:Number(f.get('returnShipping')),platformRate:Number(f.get('platformRate')),cardRate:Number(f.get('cardRate')),returnRateThreshold:Number(f.get('returnRateThreshold'))};const undatedInbound=Number(f.get('undatedInbound')),inboundDate=String(f.get('inboundDate')||'');const expenses=inboundDate&&undatedInbound>0?[...shop.expenses,{id:'CP-'+crypto.randomUUID().slice(0,8),date:inboundDate,category:'Vận chuyển về kho',name:'Phí về kho từ dữ liệu lịch sử',amount:undatedInbound,note:'Gán ngày cho khoản chi trước đây chưa có ngày'}]:shop.expenses;await persist({...shop,settings,expenses,undatedInbound:inboundDate?0:undatedInbound});}}>{[['shipping','Ship đi + bao bì (₫)'],['returnShipping','Ship hoàn (₫)'],['platformRate','Phí Facebook (% Ads)'],['cardRate','Phí thẻ (% Ads)'],['returnRateThreshold','Ngưỡng cảnh báo tỷ lệ hoàn (%)']].map(([key,label])=><label key={key}>{label}<input name={key} type="number" min="0" max={key.includes('Rate')?100:1000000000} step={key.includes('Rate')?'0.1':'1'} required defaultValue={shop.settings[key as keyof Shop['settings']]??15}/></label>)}<label>Ship về kho chưa ngày (₫)<input name="undatedInbound" type="number" min="0" step="1" required defaultValue={shop.undatedInbound}/></label><label>Gán ngày cho khoản về kho (tùy chọn)<input name="inboundDate" type="date" max={today()}/><small>Chọn ngày để chuyển khoản chưa có ngày sang sổ chi phí, tránh tính trùng. Để trống nếu chưa xác định được.</small></label><button disabled={saving} className="button primary">{saving?'Đang lưu...':'Lưu thiết lập'}</button></form></section><div><section className="panel settings-panel"><span className="settings-leaf"><Leaf size={25}/></span><h2>Dữ liệu Emi House</h2><p>{shop.orders.filter(o=>o.sourceRow).length} đơn từ Excel</p><div className="source-file">{shop.source}</div><button className="button" onClick={()=>{saveFile('emi-house-backup-'+today()+'.json',JSON.stringify(shop,null,2),'application/json');toast('Đã tải bản sao lưu đầy đủ');}}><Download size={17}/>Sao lưu JSON</button></section></div></div>}
